const directoryHex="";
function decodeHex(hex) {
  return Uint8Array.from(hex.match(/../g), pair => parseInt(pair, 16));
}
async function collectionZip(progress) {
  const chunks = [];
  for (const [name, header] of entries) {
    const response = await fetch('art/' + encodeURIComponent(name));
    if (!response.ok) throw new Error('Wallpaper unavailable');
    chunks.push(decodeHex(header), await response.blob());
    progress(chunks.length / 2);
  }
  return new Blob([...chunks, decodeHex(directoryHex)], {type:'application/zip'});
}
const downloadButton = document.querySelector('#downloadAll');
downloadButton.onclick = async () => {
  downloadButton.disabled = true;
  downloadButton.textContent = 'Preparing ZIP…';
  try {
    const zip = await collectionZip(count => {downloadButton.textContent = 'Preparing ' + count + ' / ' + entries.length});
    const url = URL.createObjectURL(zip);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'Sayyid-Edition.zip';
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
    downloadButton.textContent = 'Download all 32 · ZIP';
  } catch {
    downloadButton.textContent = 'Retry ZIP download';
  } finally {
    downloadButton.disabled = false;
  }
};
